<script setup lang="ts">
import { EditPen, Plus, RefreshRight, VideoPlay, WarningFilled } from '@element-plus/icons-vue';
import { computed, inject, onMounted, reactive, ref } from 'vue';
import { ElMessage, ElMessageBox } from 'element-plus';
import AdminShell from '../layouts/AdminShell.vue';
import { allowedActions, statusLabel, type Video, type VideoAction, type VideoQuery, type VideoRepository, type VideoStatus, type VideoUpdate } from '../features/video/model';
import { videoRepositoryKey } from '../features/video/repository';

const repository = inject<VideoRepository>(videoRepositoryKey);
if (!repository) throw new Error('Video repository is not configured');
const videoRepository: VideoRepository = repository;
const mockMode = import.meta.env.VITE_USE_DASHBOARD_MOCK !== 'false';
const items = ref<Video[]>([]); const total = ref(0); const loading = ref(true); const refreshing = ref(false); const error = ref<string>();
const query = reactive<VideoQuery>({ page: 1, pageSize: 20, keyword: '', status: undefined, category: undefined });
const selected = ref<Video[]>([]); const detail = ref<Video>(); const detailOpen = ref(false); const editorOpen = ref(false); const reasonOpen = ref(false); const reason = ref(''); const actionTarget = ref<Video>(); const action = ref<'offShelf' | 'batchOffShelf'>('offShelf'); const rowLoading = ref(''); const requestId = ref(0);
const form = reactive<VideoUpdate>({ title: '', description: '', category: '', tags: [], visibility: 'PUBLIC' });
const categories = ['企业文化', '安全生产', '技能培训'];
const videoStatuses: VideoStatus[] = ['DRAFT', 'PENDING_REVIEW', 'PUBLISHED', 'OFF_SHELF', 'TRANSCODING', 'TRANSCODE_FAILED', 'REJECTED'];
const eligiblePublished = computed(() => selected.value.filter((item) => item.status === 'PUBLISHED'));
const eligibleOffShelf = computed(() => selected.value.filter((item) => item.status === 'OFF_SHELF'));
function time(value: string | null) { return value ? new Intl.DateTimeFormat('zh-CN', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false, timeZone: 'Asia/Shanghai' }).format(new Date(value)) : '--'; }
function duration(value: number) { return value ? `${Math.floor(value / 60)}:${String(value % 60).padStart(2, '0')}` : '--'; }
function tagType(status: VideoStatus) { return status === 'PUBLISHED' ? 'success' : status === 'OFF_SHELF' || status === 'REJECTED' || status === 'TRANSCODE_FAILED' ? 'danger' : status === 'PENDING_REVIEW' ? 'warning' : 'info'; }
function can(video: Video, item: VideoAction) { return allowedActions[video.status].includes(item); }
async function load() { const id = ++requestId.value; const initial = !items.value.length; loading.value = initial; refreshing.value = !initial; error.value = undefined; try { const result = await videoRepository.list(query); if (id !== requestId.value) return; items.value = result.items; total.value = result.total; } catch (caught) { if (id === requestId.value) error.value = caught instanceof Error ? caught.message : '视频数据加载失败'; } finally { if (id === requestId.value) { loading.value = false; refreshing.value = false; } } }
function search() { query.page = 1; void load(); } function reset() { query.keyword = ''; query.status = undefined; query.category = undefined; query.page = 1; void load(); }
async function openDetail(video: Video) { detailOpen.value = true; detail.value = undefined; try { detail.value = await videoRepository.get(video.id); } catch (caught) { ElMessage.error(caught instanceof Error ? caught.message : '详情加载失败'); } }
async function openEdit(video: Video) { const item = await videoRepository.get(video.id); actionTarget.value = item; Object.assign(form, { title: item.title, description: item.description, category: item.category, tags: item.tags, visibility: item.visibility }); editorOpen.value = true; }
async function save() { if (!form.title.trim()) return ElMessage.error('请输入标题'); if (!form.category) return ElMessage.error('请选择分类'); rowLoading.value = `edit-${actionTarget.value?.id}`; try { await videoRepository.update(actionTarget.value!.id, { ...form, title: form.title.trim() }); editorOpen.value = false; await load(); ElMessage.success('视频信息已更新'); } catch (caught) { ElMessage.error(caught instanceof Error ? caught.message : '保存失败'); } finally { rowLoading.value = ''; } }
async function submit(video: Video) { await execute(video, 'submitReview'); }
async function execute(video: Video, operation: 'submitReview' | 'restore' | 'retryTranscode') { try { await ElMessageBox.confirm(`确认${operation === 'submitReview' ? '提交审核' : operation === 'restore' ? '恢复上架' : '重新发起转码'}《${video.title}》？`, '确认操作', { type: 'warning' }); rowLoading.value = `${operation}-${video.id}`; if (operation === 'submitReview') await videoRepository.submitReview(video.id); if (operation === 'restore') await videoRepository.restore(video.id); if (operation === 'retryTranscode') await videoRepository.retryTranscode(video.id); await load(); if (detail.value?.id === video.id) detail.value = await videoRepository.get(video.id); ElMessage.success('操作已提交'); } catch (caught) { if (caught !== 'cancel' && caught !== 'close') ElMessage.error(caught instanceof Error ? caught.message : '操作失败'); } finally { rowLoading.value = ''; } }
function openReason(video?: Video) { action.value = video ? 'offShelf' : 'batchOffShelf'; actionTarget.value = video; reason.value = ''; reasonOpen.value = true; }
async function confirmOffShelf() { if (!reason.value.trim()) return ElMessage.error('请输入下架原因'); try { const ids = action.value === 'offShelf' ? [actionTarget.value!.id] : eligiblePublished.value.map((item) => item.id); await ElMessageBox.confirm(`确认下架 ${ids.length} 个视频？下架后将停止公开展示。`, '确认下架', { type: 'warning', confirmButtonText: '确认下架' }); rowLoading.value = 'off-shelf'; if (action.value === 'offShelf') await videoRepository.offShelf(ids[0], reason.value); else { const result = await videoRepository.batchOffShelf(ids, reason.value); ElMessage.info(`成功 ${result.succeededIds.length} 项，失败 ${result.failed.length} 项`); } reasonOpen.value = false; selected.value = []; await load(); ElMessage.success('下架操作已完成'); } catch (caught) { if (caught !== 'cancel' && caught !== 'close') ElMessage.error(caught instanceof Error ? caught.message : '下架失败'); } finally { rowLoading.value = ''; } }
async function batchRestore() { const ids = eligibleOffShelf.value.map((item) => item.id); if (!ids.length) return; try { await ElMessageBox.confirm(`确认恢复 ${ids.length} 个已下架视频？`, '确认恢复', { type: 'warning' }); const result = await videoRepository.batchRestore(ids); selected.value = selected.value.filter((item) => result.failed.some((failed) => failed.id === item.id)); await load(); ElMessage.info(`成功 ${result.succeededIds.length} 项，失败 ${result.failed.length} 项`); } catch (caught) { if (caught !== 'cancel' && caught !== 'close') ElMessage.error(caught instanceof Error ? caught.message : '恢复失败'); } }
async function simulateUpload(event: Event) { const file = (event.target as HTMLInputElement).files?.[0]; if (!file) return; if (!/\.(mp4|mov)$/i.test(file.name) || file.size > 2 * 1024 * 1024 * 1024) return ElMessage.error('仅支持不超过 2GB 的 MP4/MOV 文件'); await videoRepository.createSimulatedUpload(file.name); query.page = 1; await load(); ElMessage.success('已创建本地模拟上传草稿，未发送文件到服务器'); (event.target as HTMLInputElement).value = ''; }
onMounted(() => { void load(); });
</script>

<template>
  <AdminShell page-title="视频管理" page-subtitle="管理视频内容、处理状态与发布流程">
    <section class="video-page"><header class="page-header"><div><h2>视频管理</h2><p>查询并处理视频内容生命周期</p></div><div class="header-actions"><label v-if="mockMode" class="mock-upload"><Plus />模拟上传<input type="file" accept="video/mp4,video/quicktime" @change="simulateUpload" /></label><el-button :icon="RefreshRight" :loading="refreshing" @click="load">刷新</el-button></div></header>
      <div class="filters"><el-input v-model="query.keyword" placeholder="标题、视频 ID 或作者" clearable @keyup.enter="search" /><el-select v-model="query.status" placeholder="全部状态" clearable><el-option v-for="status in videoStatuses" :key="status" :label="statusLabel[status]" :value="status" /></el-select><el-select v-model="query.category" placeholder="全部分类" clearable><el-option v-for="category in categories" :key="category" :label="category" :value="category" /></el-select><el-button type="primary" @click="search">查询</el-button><el-button @click="reset">重置</el-button></div>
      <div v-if="selected.length" class="batch-bar"><span>已选择 {{ selected.length }} 项，其中可下架 {{ eligiblePublished.length }} 项、可恢复 {{ eligibleOffShelf.length }} 项</span><el-button type="danger" :disabled="!eligiblePublished.length" @click="openReason()">批量下架</el-button><el-button :disabled="!eligibleOffShelf.length" @click="batchRestore">批量恢复</el-button></div>
      <section v-if="error && !items.length" class="error-state"><el-icon><WarningFilled /></el-icon><p>{{ error }}</p><el-button @click="load">重试</el-button></section>
      <section v-else class="table-shell" v-loading="loading || refreshing"><div v-if="error" class="inline-error">{{ error }} <button type="button" @click="load">重试</button></div><el-table :data="items" @selection-change="selected = $event"><el-table-column type="selection" width="48" /><el-table-column label="视频" min-width="250"><template #default="{ row }"><button class="video-link" type="button" @click="openDetail(row)">{{ row.title }}</button><small>ID {{ row.id }} · {{ duration(row.durationSeconds) }}<span v-if="row.isSimulated"> · 模拟草稿</span></small></template></el-table-column><el-table-column prop="author" label="作者" width="130" /><el-table-column label="分类/标签" min-width="160"><template #default="{ row }"><span>{{ row.category }}</span><small>{{ row.tags.join(' · ') || '--' }}</small></template></el-table-column><el-table-column label="状态" width="110"><template #default="{ row }"><el-tag :type="tagType(row.status)" effect="plain">{{ statusLabel[row.status as VideoStatus] }}</el-tag></template></el-table-column><el-table-column label="播放/互动" width="110" align="right"><template #default="{ row }">{{ row.playCount.toLocaleString() }} / {{ row.interactionCount.toLocaleString() }}</template></el-table-column><el-table-column label="发布时间" width="140"><template #default="{ row }">{{ time(row.publishedAt) }}</template></el-table-column><el-table-column label="操作" width="255" fixed="right"><template #default="{ row }"><el-button link :icon="VideoPlay" @click="openDetail(row)">详情</el-button><el-button v-if="can(row, 'edit')" link :icon="EditPen" @click="openEdit(row)">编辑</el-button><el-button v-if="can(row, 'submitReview')" link type="primary" @click="submit(row)">提交审核</el-button><el-button v-if="can(row, 'offShelf')" link type="danger" @click="openReason(row)">下架</el-button><el-button v-if="can(row, 'restore')" link type="primary" @click="execute(row, 'restore')">恢复</el-button><el-button v-if="can(row, 'retryTranscode')" link type="warning" @click="execute(row, 'retryTranscode')">重试转码</el-button></template></el-table-column></el-table><el-pagination v-if="total" v-model:current-page="query.page" :page-size="query.pageSize" :total="total" layout="total, prev, pager, next" @current-change="load" /></section>
    </section>
    <el-drawer v-model="detailOpen" title="视频详情" size="480px"><div v-if="detail" class="detail"><div class="preview"><video v-if="detail.previewUrl" :src="detail.previewUrl" controls /><p v-else>预览暂不可用</p></div><h3>{{ detail.title }}</h3><el-tag :type="tagType(detail.status)">{{ statusLabel[detail.status] }}</el-tag><p>{{ detail.description }}</p><dl><div><dt>作者</dt><dd>{{ detail.author }}</dd></div><div><dt>分类</dt><dd>{{ detail.category }}</dd></div><div><dt>可见范围</dt><dd>{{ detail.visibility === 'PUBLIC' ? '公开' : '仅内部' }}</dd></div><div><dt>更新时间</dt><dd>{{ time(detail.updatedAt) }}</dd></div></dl><p v-if="detail.transcodeError" class="diagnostic">转码诊断：{{ detail.transcodeError }}</p><p v-if="detail.offShelfReason" class="diagnostic">下架原因：{{ detail.offShelfReason }}</p></div><el-skeleton v-else :rows="8" animated /></el-drawer>
    <el-dialog v-model="editorOpen" title="编辑视频信息" width="520px"><el-form label-position="top"><el-form-item label="标题" required><el-input v-model="form.title" maxlength="100" show-word-limit /></el-form-item><el-form-item label="简介"><el-input v-model="form.description" type="textarea" :rows="3" maxlength="500" show-word-limit /></el-form-item><el-form-item label="分类" required><el-select v-model="form.category"><el-option v-for="category in categories" :key="category" :label="category" :value="category" /></el-select></el-form-item><el-form-item label="标签"><el-select v-model="form.tags" multiple allow-create filterable default-first-option /></el-form-item><el-form-item label="可见范围"><el-radio-group v-model="form.visibility"><el-radio value="PUBLIC">公开</el-radio><el-radio value="INTERNAL">仅内部</el-radio></el-radio-group></el-form-item></el-form><template #footer><el-button @click="editorOpen = false">取消</el-button><el-button type="primary" :loading="rowLoading.startsWith('edit')" @click="save">保存</el-button></template></el-dialog>
    <el-dialog v-model="reasonOpen" title="下架视频" width="440px"><p>请说明下架原因。视频下架后将停止公开展示。</p><el-input v-model="reason" type="textarea" :rows="3" maxlength="200" show-word-limit placeholder="例如：内容需要更新" /><template #footer><el-button @click="reasonOpen = false">取消</el-button><el-button type="danger" :loading="rowLoading === 'off-shelf'" @click="confirmOffShelf">下一步确认</el-button></template></el-dialog>
  </AdminShell>
</template>

<style scoped>
.video-page { display: grid; gap: 16px; }.page-header { display: flex; align-items: end; justify-content: space-between; }.page-header h2 { margin: 0; font-size: 20px; }.page-header p { margin: 6px 0 0; color: var(--yl-text-muted); font-size: 12px; }.header-actions, .filters, .batch-bar { display: flex; align-items: center; gap: 10px; }.mock-upload { display: inline-flex; align-items: center; gap: 5px; height: 32px; padding: 0 12px; color: #fff; background: var(--yl-indigo); border-radius: 4px; font-size: 13px; cursor: pointer; }.mock-upload input { display: none; }.filters { padding: 14px; background: var(--yl-surface); border: 1px solid var(--yl-border); border-radius: 8px; }.filters .el-input { width: 270px; }.filters .el-select { width: 135px; }.batch-bar { padding: 10px 14px; color: var(--yl-text-secondary); background: #f7f8ff; border: 1px solid #dfe3ff; border-radius: 6px; font-size: 12px; }.batch-bar .el-button:first-of-type { margin-left: auto; }.table-shell { overflow: hidden; min-height: 300px; background: var(--yl-surface); border: 1px solid var(--yl-border); border-radius: 8px; }.video-link { max-width: 100%; padding: 0; overflow: hidden; color: var(--yl-text); background: transparent; border: 0; font-weight: 600; text-align: left; text-overflow: ellipsis; white-space: nowrap; cursor: pointer; }.video-link:hover { color: var(--yl-indigo); }.el-table small { display: block; margin-top: 3px; color: var(--yl-text-muted); font-size: 10px; }.el-pagination { justify-content: flex-end; padding: 14px 18px; }.inline-error { padding: 9px 14px; color: #9f3b42; background: #fff6f6; font-size: 12px; }.inline-error button { margin-left: 8px; color: inherit; background: none; border: 0; text-decoration: underline; cursor: pointer; }.error-state { display: grid; justify-items: center; gap: 10px; padding: 70px; background: var(--yl-surface); border: 1px solid var(--yl-border); border-radius: 8px; }.error-state .el-icon { color: var(--yl-coral); font-size: 28px; }.detail { display: grid; gap: 14px; }.detail h3, .detail p { margin: 0; }.preview { display: grid; place-items: center; min-height: 210px; color: var(--yl-text-muted); background: #f2f4f8; border-radius: 6px; }.preview video { width: 100%; }.detail dl { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; margin: 0; }.detail dt { color: var(--yl-text-muted); font-size: 11px; }.detail dd { margin: 5px 0 0; font-size: 13px; }.diagnostic { padding: 10px; color: #914245; background: #fff6f6; border-radius: 5px; font-size: 12px; }
</style>
